add('F016',null,async h=>{
 await h.expect(h.page.locator('#welcome')).toBeVisible();
 const themes=[];
 for(const [choice,label] of [['dark','深色'],['sepia','护眼'],['auto','自动'],['light','浅色']]){
  await h.step('在主页切换'+label+'主题',()=>h.click('#btn-theme'));
  await h.expect.poll(()=>h.page.evaluate(()=>state.theme)).toBe(choice);
  await h.expect(h.page.locator('#btn-theme')).toHaveAttribute('data-theme-icon',choice);
  await h.expect(h.page.locator('#welcome')).toBeVisible();
  const theme=await h.page.evaluate(async()=>{
   if(await settingsSaveQueue!==true)throw Error('Theme preference was not saved');
   return{choice:state.theme,resolved:document.body.dataset.theme,background:getComputedStyle(document.body).backgroundColor,saved:JSON.parse(localStorage.getItem('readmd-settings')).theme,system:matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'};
  });
  if(theme.saved!==choice||theme.resolved!==(choice==='auto'?theme.system:choice))throw Error('Home theme did not apply or persist');
  themes.push(theme);
 }
 if(themes[0].background===themes[3].background)throw Error('Home dark/light colors did not change');
 await h.step('打开阅读手册，调整字号',async()=>{await h.open();await h.click('#btn-A');});
 const larger=await h.page.evaluate(()=>state.fontSize);
 await h.click('#btn-a');
 if(await h.page.evaluate(()=>state.fontSize)>=larger)throw Error('Reader font controls did not change size');
 await h.step('进入禅模式，专注阅读',()=>h.click('#btn-zen'));
 await h.expect(h.page.locator('body')).toHaveClass(/zen-mode/);
 await h.page.keyboard.press('Escape');
 await h.expect(h.page.locator('body')).not.toHaveClass(/zen-mode/);
 h.evidence.push({assertion:'home_theme_cycle_applies_and_persists_with_reader_controls',themes,fontSizeRestored:true,zenExited:true});
},{hideToast:true,posterAt:1.2});
