add('F041',read,async h=>{await h.step('打开 AI 侧栏',()=>h.click('#btn-ai'));await h.step('展开全屏对话',()=>h.click('#ai-expand-toggle'));await h.click('#ai-expand-toggle');const b=await h.page.locator('#ai-resize-handle').boundingBox();if(b)await h.step('拖动调整对话宽度',async()=>{await h.page.mouse.move(b.x+b.width/2,b.y+90);await h.page.mouse.down();await h.page.mouse.move(b.x-90,b.y+90,{steps:8});await h.page.mouse.up();});await h.click('#ai-close');h.evidence.push({assertion:'ai_panel_expansion_resize_close'});});
