recipes.F058={native:true,prepare:async h=>{
 const dir=path.join(h.materials,'conversion-demo');fs.mkdirSync(dir);
 for(const n of ['研究数据.csv','讨论邀请.eml'])fs.copyFileSync(path.join(h.materials,n),path.join(dir,n));
 fs.writeFileSync(path.join(dir,'研究数据.md'),'# 原有阅读统计\n\n这份输出需要先保留。\n');
 fs.writeFileSync(path.join(dir,'目录入口.md'),'# 转换工作坊\n\n比较文件导入、目录收集与覆盖策略。\n');
 h.convertDemoDir=dir;await h.open('conversion-demo/目录入口.md');await h.more('btn-convert');
},run:async h=>{
 await h.step('选择演示资料文件夹，已有 Markdown 自动跳过',async()=>{const chosen=h.native('dialog',h.convertDemoDir,true);await h.click('#convert-folder');await chosen;});
 await h.expect.poll(()=>h.page.locator('.batch-item.ok,.batch-item.skipped').count(),{timeout:30000}).toBe(2);
 const target=path.join(h.convertDemoDir,'研究数据.md');if(!fs.readFileSync(target,'utf8').includes('这份输出需要先保留'))throw Error('Default batch replaced existing Markdown');
 await h.step('明确勾选覆盖，重新转换并保留旧版本',()=>h.page.locator('#convert-overwrite').check());
 const chosen=h.native('dialog',h.convertDemoDir,true);await h.click('#convert-folder');await chosen;
 await h.expect.poll(()=>h.page.locator('.batch-item.ok').count(),{timeout:30000}).toBe(2);
 if(!fs.readFileSync(target,'utf8').includes('认识与经验'))throw Error('Explicit overwrite did not save converted data');
 const history=await h.api('/api/documents/history');if(!history.entries.some(e=>e.kind==='version'))throw Error('Overwrite did not retain a version');
 h.evidence.push({assertion:'native_folder_real_csv_eml_default_skip_explicit_overwrite_and_history'});
}};
recipes.F075={native:true,prepare:exportPrepare,run:async h=>{await h.reveal('#export-print');await h.page.evaluate(()=>{window.addEventListener('beforeprint',()=>console.info('showcase-system-print-open'),{once:true});window.addEventListener('afterprint',()=>window.showcasePrintClosed=true,{once:true});});await h.step('打开系统打印预览，查看当前正文后取消',async()=>{const opened=h.page.waitForEvent('console',{predicate:m=>m.text()==='showcase-system-print-open'});const clicking=h.click('#export-print');clicking.catch(()=>{});await opened;await h.delay(1700);await h.native('print-cancel');await clicking;});await h.expect.poll(()=>h.page.evaluate(()=>!!window.showcasePrintClosed)).toBe(true);h.evidence.push({assertion:'actual_browser_beforeprint_native_escape_afterprint'});}};
