recipes.F101={native:true,prepare:webPrepare,run:async h=>{
 const fixture=await webFixture(h.materials);let auxBrowser;
 try{
  await h.page.locator('#url-private').check();await h.page.locator('#url-input').fill(fixture.url+'/dynamic');const before=new Set(h.debugPorts());
  await h.step('打开隔离网页窗口，进入原创演示会话',()=>h.click('#url-go'));
  await h.expect.poll(()=>h.debugPorts().find(p=>!before.has(p)),{timeout:30000}).toBeTruthy();
  const port=h.debugPorts().find(p=>!before.has(p));auxBrowser=await h.chromium.connectOverCDP('http://127.0.0.1:'+port);
  const aux=auxBrowser.contexts().flatMap(c=>c.pages()).find(p=>p.url().startsWith(fixture.url));if(!aux)throw Error('Own authorization page missing');
  await h.native('resize-aux');h.capturePage=aux;await aux.locator('#demo-login').click();await h.delay(550);
  if(await aux.evaluate(()=>typeof window.pywebview)!=='undefined')throw Error('External page exposed reader bridge');
  await h.step('明确授权本次提取，返回真实正文',()=>aux.locator('#readmd-capture-bar button').click());
  await h.expect.poll(()=>h.page.evaluate(()=>webRun.running),{timeout:30000}).toBe(false);
  await h.expect(h.page.locator('#content')).toContainText('已进入演示会话',{timeout:30000});await h.expect.poll(()=>h.page.evaluate(()=>webRun.privateGrant)).toBe('');
  h.evidence.push({assertion:'real_private_grant_cookies_capture_and_revocation'});
 }finally{h.capturePage=null;await auxBrowser?.close().catch(()=>{});await fixture.close();}
}};


